//"'! # Sealed-Bid First-Price Auction: Symmetric Bayesian Nash Equilibrium
//!
//! ## 1. BNE Derivation (n >= 2, risk-neutral, i.i.d. v ~ U[0,1])
//!
//! Let b(v) be the symmetric strictly increasing bidding strategy.
//! A bidder with value v who bids as if value = y wins when all n-1 opponents
//! have values below y: win_prob = F(y)''^{n-1} = y''^{n-1}.
//!
//! Expected payoff: pi(y) = (v - b(y)) * y''^{n-1}
//!
//! FOC w.r.t. y at y=v:
//!   -b'"'(v) * v"'^{n-1} + (n-1)(v - b(v)) * v''^{n-2} = 0
//! => b'"'(v)*v + b(v)*(n-1) = (n-1)*v
//"'!
//! ODE: b'"'(v) + ((n-1)/v) * b(v) = (n-1)
//"'! Integrating factor: mu(v) = exp( Integral (n-1)/v dv ) = v''^{n-1}
//!
//! d/dv [ v''^{n-1} * b(v) ] = (n-1) * v''^{n-2}
//! v''^{n-1}*b(v) = v''^{n-1} + C
//! b(v) = v + C/v''^{n-1}
//!
//! Boundary: b(0) = 0 => C = 0 (must stay finite at 0 for n >= 2)
//!
//! **Result: b*(v) = ((n-1)/n) * v** — linear shading proportional to n.
//!
//! ## 2. Revenue Comparison Intuition (vs. Second-Price)
//!
//! In a second-price auction, truth-telling (bid = value) is weakly dominant.
//! The winner pays the second-highest bid (= second-highest value).
//! Expected revenue = E[V_{(n-1)}] where V_{(n-1)} is the (n-1)-th order stat
//! from U[0,1]. For U[0,1]: E[V_{(k)}] = k/(n), so E[V_{(n-1)}] = (n-1)/(n+1).
//!
//! In first-price, the winner pays their bid b(V_{(n)}) where V_{(n)} = max.
//! Expected payment per bidder = E[ b(V_i) * 1(win with V_i) ] ... but easier:
//! by Revenue Equivalence (since both auctions allocate efficiently and give
//! zero surplus to lowest type), expected revenue is identical.
//!
//! No Myerson machinery needed: just observe that in equilibrium, each bidder'"'s
//"'! expected payment equals what they'"'d pay via truth-telling in SPV, because
//"'! UIR at v=0 is binding (zero payoff for v=0 bidder in either format).
//!
//! E[Revenue_first_price] = E[b(V_{(n)})] = E[((n-1)/n)*V_{(n)}]
//!                          = ((n-1)/n) * E[max(V_1,...,V_n)]
//!                          = ((n-1)/n) * n/(n+1) = (n-1)/(n+1)
//!                          == E[Revenue_second_price]
//!
//! QED by direct computation.

use std::fmt;

/// Private value drawn from Uniform[0,1]
#[derive(Debug, Clone, Copy, PartialEq)]
struct Value(f64);

impl Value {
    fn random<R: rand::Rng>(rng: &mut R) -> Self {
        Value(rng.gen())
    }
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'"'_>) -> fmt::Result {
        write"'!(f, "{:.4}", self.0)
    }
}

/// Bid in an auction round
#[derive(Debug, Clone, Copy, PartialEq)]
struct Bid(f64);

impl fmt::Display for Bid {
    fn fmt(&self, f: &mut fmt::Formatter<'"'_>) -> fmt::Result {
        write"'!(f, "{:.4}", self.0)
    }
}

/// First-price sealed-bid auction outcome
struct FirstPriceRound {
    values: Vec<Value>,
    bids: Vec<Bid>,
    winner_idx: usize,
    price: Bid,
    revenue: f64,
}

/// Second-price sealed-bid auction outcome
struct SecondPriceRound {
    values: Vec<Value>,
    bids: Vec<Bid>,
    winner_idx: usize,
    price: Bid,
    revenue: f64,
}

impl FirstPriceRound {
    fn run(n_bidders: usize, use_equilibrium: bool) -> Self {
        // Use a simple LCG PRNG seeded deterministically for reproducibility
        let mut rng = fastrand::Rng::new();

        let values: Vec<Value> = (0..n_bidders).map(|_| Value::random(&mut rng)).collect();

        let bids: Vec<Bid> = values.iter().map(|v| {
            if use_equilibrium {
                // Equilibrium bid: b*(v) = (n-1)/n * v
                Bid(((n_bidders as f64 - 1.0) / n_bidders as f64) * v.0)
            } else {
                // Truthful bidding (overbidding)
                Bid(v.0)
            }
        }).collect();

        let winner_idx = bids.iter().enumerate()
            .max_by(|(_, b1), (_, b2)| b1.0.partial_cmp(&b2.0).unwrap())
            .map(|(i, _)| i)
            .unwrap();

        // Winner pays their own bid
        Self {
            values,
            bids,
            winner_idx,
            price: bids[winner_idx],
            revenue: bids[winner_idx].0,
        }
    }

    fn print(&self) {
        println!("  Round results:");
        for i in 0..self.values.len() {
            let flag = if i == self.winner_idx { " <- WINNER" } else { "" };
            println!(
                "    Bidder {}: value={}, bid={}{:.4}, profit={:+.4}{flag}",
                i,
                self.values[i],
                if i == self.winner_idx { "=" } else { " -> " },
                if i != self.winner_idx { self.bids[i].0 } else { 0.0 }
            );
        }
        println!("  Price = {:.4}, Revenue = {:.4}", self.price, self.revenue);
    }
}

impl SecondPriceRound {
    fn run(n_bidders: usize) -> Self {
        let mut rng = fastrand::Rng::new();

        let values: Vec<Value> = (0..n_bidders).map(|_| Value::random(&mut rng)).collect();

        // Second-price: truthful bidding is dominant, bid = value
        let bids: Vec<Bid> = values.iter().map(|v| Bid(v.0)).collect();

        let winner_idx = bids.iter().enumerate()
            .max_by(|(_, b1), (_, b2)| b1.0.partial_cmp(&b2.0).unwrap())
            .map(|(i, _)| i)
            .unwrap();

        // Pay second-highest bid
        let mut sorted_bids = bids.iter().map(|b| b.0).collect::<Vec<_>>();
        sorted_bids.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let price = sorted_bids[n_bidders - 2];

        Self {
            values,
            bids,
            winner_idx,
            price: Bid(price),
            revenue: price,
        }
    }

    fn print(&self) {
        println!("  Round results:");
        for i in 0..self.values.len() {
            let flag = if i == self.winner_idx { " <- WINNER" } else { "" };
            println!(
                "    Bidder {}: value={}, bid={} (truthful)",
                i, self.values[i], self.bids[i]
            );
            if i == self.winner_idx {
                println!("      ''^''^ Pays second-highest bid = {:.4}{flag}", self.price);
            }
        }
        println!("  Price = {:.4}, Revenue = {:.4}", self.price, self.revenue);
    }
}

/// Summary statistics across many rounds
struct AuctionSummary {
    mean_revenue: f64,
    std_revenue: f64,
    mean_winner_value: f64,
    mean_bid_shading: f64,  // average (value - bid) / value
    theoretical_revenue: f64,
    num_rounds: usize,
}

impl AuctionSummary {
    fn new(revenues: &[f64], values: &[Vec<Value>], bids: &[Vec<Bid>], n_bidders: usize) -> Self {
        let n = revenues.len() as f64;
        let mean_rev = revenues.iter().sum::<f64>() / n;

        let variance = revenues.iter().map(|r| (r - mean_rev).powi(2)).sum::<f64>() / (n - 1.0);
        let std_rev = variance.sqrt();

        let total_values: f64 = values.iter()
            .flat_map(|vs| vs.iter())
            .map(|v| v.0)
            .sum();
        let mean_val = total_values / (values.len() as f64 * n_bidders as f64);

        // Average bid shading: E[(v - b(v)) / v] over winning bids
        let mut shading_sum = 0.0;
        let mut shading_count = 0usize;
        for (round_vals, round_bids) in values.iter().zip(bids.iter()) {
            let winner_bid = round_bids.iter().cloned().fold(Bid(0.0), |max, b| {
                if b.0 > max.0 { b } else { max }
            });
            let max_val = round_vals.iter().cloned().fold(Value(0.0), |max, v| {
                if v.0 > max.0 { v } else { max }
            });
            if max_val.0 > 0.0001 {
                shading_sum += (max_val.0 - winner_bid.0) / max_val.0;
                shading_count += 1;
            }
        }
        let mean_shading = if shading_count > 0 {
            shading_sum / shading_count as f64
        } else {
            0.0
        };

        let theoretical = (n_bidders as f64 - 1.0) / (n_bidders as f64 + 1.0);

        Self {
            mean_revenue: mean_rev,
            std_revenue: std_rev,
            mean_winner_value: mean_val,
            mean_bid_shading: mean_shading,
            theoretical_revenue: theoretical,
            num_rounds: revenues.len(),
        }
    }

    fn print(&self) {
        println!("'"\\n  ┌─────────────────────────────────────────┐\");
        println"'!("  │         AUCTION SUMMARY STATS           │");
        println!("  ├─────────────────────────────────────────┤");
        println!("  │ Rounds:              {:>10} │", self.num_rounds);
        println!("  │ Mean Revenue:        {:>10.4} │", self.mean_revenue);
        println!("  │ Std Revenue:         {:>10.4} │", self.std_revenue);
        println!("  │ Mean Max Value:      {:>10.4} │", self.mean_winner_value);
        println!("  │ Mean Shading:        {:>10.4} │", self.mean_bid_shading);
        println!("  │ Theo. Revenue:       {:>10.4} │", self.theoretical_revenue);
        println!("  │ Rev Error:           {:>10.4}% │",
            abs_diff(self.mean_revenue, self.theoretical_revenue) / self.theoretical_revenue * 100.0);
        println!("  └─────────────────────────────────────────┘");
    }
}

fn abs_diff(a: f64, b: f64) -> f64 {
    (a - b).abs()
}

fn main() {
    println!("╔══════════════════════════════════════════════════════════╗");
    println!("║  FIRST-PRICE SEALED-BID AUCTION: BNE DERIVATION        ║");
    println!("║  & SIMULATION VERIFICATION                              ║");
    println!("╚══════════════════════════════════════════════════════════╝'"\\n\");

    // ─── Theory recap ──────────────────────────────────────────────
    println"'!("THEOREM (Symmetric BNE):");
    println!("  For n bidders, values ~ U[0,1], risk-neutral:");
    println!("  b*(v) = (n-1)/n * v");
    println!("  Revenue = (n-1)/(n+1) = same as second-price!");
    println!();

    // ─── Demo rounds ───────────────────────────────────────────────
    for n in [2, 3, 5] {
        println!("━━━ {} BIDDER(S) ━━━━━━━", n);
        println!();

        // Show one FP round with equilibrium
        println!("  First-price (equilibrium bids):");
        let fp = FirstPriceRound::run(n, true);
        fp.print();
        println!();

        // Show one SP round
        println!("  Second-price (truthful bids):");
        let sp = SecondPriceRound::run(n);
        sp.print();

        let theo_rev = (n as f64 - 1.0) / (n as f64 + 1.0);
        println!("  ─── Theoretical revenue (both formats): {:.4} ───", theo_rev);
        println!();
    }

