/// Simulated human responses for testing analysis pipeline
fn generate_mock_human_bids(n_rounds: usize, n_bidders: usize, randomness: f64) -> Vec<HumanAuctionRound> {
    use std::time::{SystemTime, UNIX_EPOCH};
    let seed = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs() as u64;
    let mut rng = fastrand::Rng::with_seed(seed);

    let mut rounds = Vec::with_capacity(n_rounds);
    let mut pid_counter = 0u32;

    for round_id in 1..=n_rounds {
        let mut bidders = Vec::with_capacity(n_bidders);
        pid_counter += 1;

        for bidder_num in 0..n_bidders {
            let pid = ParticipantId(pid_counter + bidder_num as u32);
            let norm_val = rng.gen_range(0.0..1.0);
            let value_type = ValueType::from_uniform(norm_val);
            let actual_value = value_type.value();

            // Human behavior model: mix of BNE prediction + noise + systematic bias
            let bne_bid = ((n_bidders as f64 - 1.0) / n_bidders as f64) * actual_value;
            // Add Gaussian-ish noise and possible biases
            let noise = rng.gen_range(-randomness * actual_value..randomness * actual_value);
            let underbid_bias = rng.gen_range(0.0..actual_value * 0.08); // tend to underbid slightly
            let human_bid = bne_bid - underbid_bias + noise;
            let clamped_bid = human_bid.max(0.0).min(actual_value);

            // Some bidders might naively shade 50% regardless of n
            let naive_flag = rng.gen_bool(0.15); // 15% chance of naive behavior
            let final_bid = if naive_flag { actual_value * 0.5 } else { clamped_bid };

            let strategy = if naive_flag {
                Some("naive(50%)".to_string())
            } else if (final_bid - bne_bid).abs() < actual_value * 0.05 {
                Some("near-BNE".to_string())
            } else {
                None
            };

            bidders.push((pid, value_type, HumanBid { raw_bid: final_bid, strategy_label: strategy }));
        }

        // Determine winner (highest bid)
        let winner_idx = (0..n_bidders).max_by(|&a, &b| {
            bidders[a].2.raw_bid.partial_cmp(&bidders[b].2.raw_bid).unwrap()
        }).unwrap();

        let winning_bid = bidders[winner_idx].2.raw_bid;
        let winning_value = bidders[winner_idx].1.value();
        let shading = 1.0 - winning_bid / winning_value;

        rounds.push(HumanAuctionRound {
            round_id,
            n_bidders,
            bidders,
            winner_idx,
            winning_bid,
            winning_value,
            shading,
        });
    }

    rounds
}

