    bids: Vec<Bid>,
    winner_idx: usize,
    price: Bid,
    revenue: f64,
}

fn max_bid_index(bids: &[Bid]) -> usize {
    bids.iter()
        .enumerate()
        .max_by(|(_, b1), (_, b2)| b1.0.partial_cmp(&b2.0).unwrap())
        .map(|(i, _)| i)
        .unwrap()
}

