        };
        let winner_idx = max_bid_index(&bids);
        Self {
            values,
            bids,
            winner_idx,
            price: bids[winner_idx],
            revenue: bids[winner_idx].0,
        }
    }

    fn print(&self) {
        println!("  Round results:");
        for i in 0..self.values.len() {
            let flag = if i == self.winner_idx { " <-- WINNER" } else { "" };
            let label = if i == self.winner_idx { "=" } else { " -> " };
            let bid_val = if i != self.winner_idx { self.bids[i].0 } else { 0.0 };
            let profit = if i == self.winner_idx {
                self.values[i].0 - self.price.0
            } else {
                0.0
            };
            println!(
                "    Bidder {}: value={}, bid{}{}, profit={:+.4}{flag}",
                i, self.values[i], label, self.bids[i], profit
            );
        }
        println!("  Price = {:.4}, Revenue = {:.4}", self.price, self.revenue);
    }
}

impl SecondPriceRound {
    fn run(n_bidders: usize) -> Self {
        let mut rng = fastrand::Rng::new();
        let values: Vec<Value> = (0..n_bidders).map(|_| Value::random(&mut rng)).collect();
        // Second-price: truthful bidding is weakly dominant, bid = value
        let bids: Vec<Bid> = values.iter().map(|v| Bid(v.0)).collect();
        let winner_idx = max_bid_index(&bids);
        // Pay second-highest bid
        let mut sorted: Vec<f64> = bids.iter().map(|b| b.0).collect();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let price = sorted[n_bidders - 2];
        Self {
            values,
            bids,
            winner_idx,
            price: Bid(price),
            revenue: price,
        }
    }

    fn print(&self) {
        println!("  Round results:");
        for i in 0..self.values.len() {
            println!(
                "    Bidder {}: value={}, bid={} (truthful)",
                i, self.values[i], self.bids[i]
            );
            if i == self.winner_idx {
                println!("      ''^''^ Pays second-highest bid = {:.4} <-- WINNER", self.price);
            }
        }
        println!("  Price = {:.4}, Revenue = {:.4}", self.price, self.revenue);
    }
}

struct AuctionSummary {
    mean_revenue: f64,
    std_revenue: f64,
    mean_winner_value: f64,
    mean_bid_shading: f64,
    theoretical_revenue: f64,
    num_rounds: usize,
}

fn pct(val: f64) -> String {
    format!("{:.2}%", val * 100.0)
}

impl AuctionSummary {
    fn new(revenues: &[f64], values: &[Vec<Value>], bids: &[Vec<Bid>], n_bidders: usize) -> Self {
        let n = revenues.len() as f64;
        let mean_rev = revenues.iter().sum::<f64>() / n;
        let variance = revenues.iter().map(|r| (r - mean_rev).powi(2)).sum::<f64>() / (n - 1.0);
        let std_rev = variance.sqrt();

        let total_values: f64 = values.iter()
            .flat_map(|vs| vs.iter())
            .map(|v| v.0)
            .sum();
        let mean_val = total_values / (values.len() as f64 * n_bidders as f64);

        // Average bid shading over winning bids
        let mut shading_sum = 0.0;
        let mut shading_count = 0usize;
        for (round_vals, round_bids) in values.iter().zip(bids.iter()) {
            let winner_bid = round_bids.iter().cloned().fold(Bid(0.0), |m, b| {
                if b.0 > m.0 { b } else { m }
            });
            let max_val = round_vals.iter().cloned().fold(Value(0.0), |m, v| {
                if v.0 > m.0 { v } else { m }
            });
            if max_val.0 > 0.0001 {
                shading_sum += (max_val.0 - winner_bid.0) / max_val.0;
                shading_count += 1;
            }
        }
        let mean_shading = if shading_count > 0 {
            shading_sum / shading_count as f64
        } else {
            0.0
        };

        let theoretical = (n_bidders as f64 - 1.0) / (n_bidders as f64 + 1.0);

        Self {
            mean_revenue: mean_rev,
            std_revenue: std_rev,
            mean_winner_value: mean_val,
            mean_bid_shading: mean_shading,
            theoretical_revenue: theoretical,
            num_rounds: revenues.len(),
        }
    }

    fn print(&self) {
        println!("  +---------------------------------------+");
        println!("  |         AUCTION SUMMARY STATS         |");
        println!("  +---------------------------------------+");
        println!("  | Rounds:              {:>15} |", self.num_rounds);
        println!("  | Mean Revenue:        {:>15.6} |", self.mean_revenue);
        println!("  | Std Revenue:         {:>15.6} |", self.std_revenue);
        println!("  | Mean Max Value:      {:>15.6} |", self.mean_winner_value);
        println!("  | Mean Shading:        {:>15} |", pct(self.mean_bid_shading));
        println!("  | Theo. Revenue:       {:>15.6} |", self.theoretical_revenue);
        let rev_err = (self.mean_revenue - self.theoretical_revenue).abs() / self.theoretical_revenue * 100.0;
        println!("  | Rev Error:           {:>15} |", format!("{:.4}%", rev_err));
        println!("  +---------------------------------------+");
    }
}

fn abs_diff(a: f64, b: f64) -> f64 {
    (a - b).abs()
}

