/// Generate mock human bids for analysis pipeline testing
fn generate_mock_human_bids(n_rounds: usize, n_bidders: usize, randomness: f64) -> Vec<HumanAuctionRound> {
    let mut rng = fastrand::Rng::new();
    let mut rounds = Vec::with_capacity(n_rounds);
    let mut pid_counter: u32 = 0;

    for round_id in 1..=n_rounds {
        let mut bidders = Vec::with_capacity(n_bidders);
        pid_counter += 1;

        for bidder_num in 0..n_bidders {
            let pid = ParticipantId(pid_counter + bidder_num as u32);
            let norm_val = fastrand::f64(0.0..1.0);
            let value_type = ValueType::from_uniform(norm_val);
            let actual_value = value_type.value();

            // BNE equilibrium bid + noise + systematic bias
            let bne_bid = ((n_bidders as f64 - 1.0) / n_bidders as f64) * actual_value;
            let noise_margin = randomness * actual_value;
            let noise = fastrand::f64(-noise_margin..noise_margin);
            let underbid_bias = fastrand::f64(0.0..actual_value * 0.08);
            let human_bid = bne_bid - underbid_bias + noise;
            let clamped_bid = human_bid.max(0.0).min(actual_value);

            // 15% chance of naive behavior (always bid ~50%)
            let naive_flag = fastrand::bool();
            let final_bid = if naive_flag { actual_value * 0.5 } else { clamped_bid };

            let strategy = if naive_flag {
                Some("naive(50%)".to_string())
            } else if (final_bid - bne_bid).abs() < actual_value * 0.05 {
                Some("near-BNE".to_string())
            } else {
                None
            };

            bidders.push((pid, value_type, HumanBid {
                raw_bid: final_bid,
                strategy_label: strategy,
            }));
        }

        let winner_idx = bidders.iter().enumerate()
            .max_by(|(_, b1), (_, b2)| b1.2.raw_bid.partial_cmp(&b2.2.raw_bid).unwrap())
            .map(|(i, _)| i)
            .unwrap();

        let winning_bid = bidders[winner_idx].2.raw_bid;
        let winning_value = bidders[winner_idx].1.value();
        let shading = if winning_value > 0.0001 {
            1.0 - winning_bid / winning_value
        } else {
            0.0
        };

        rounds.push(HumanAuctionRound {
            round_id, n_bidders, bidders, winner_idx,
            winning_bid, winning_value, shading,
        });
    }
    rounds
}

/// Run statistical analysis on auction rounds
fn run_analysis(rounds: &[HumanAuctionRound], plan: &AnalysisPlan) {
    println!("'"\\n======================================================\");
    println"'!("  PRIMARY STATISTICAL TESTS");
    println!("======================================================'"\\n\");

    let n = rounds.len();
    let shadings: Vec<f64> = rounds.iter().map(|r| r.shading).collect();
    let mean_shading = shadings.iter().sum::<f64>() / n as f64;

    let target_bne = 1.0 - plan.theorized_shading_fraction; // 1/3 ~ 0.333
    let target_naive = 0.50;

    // Standard error
    let variance = shadings.iter().map(|s| (s - mean_shading).powi(2)).sum::<f64>() / (n as f64 - 1.0);
    let se = (variance / n as f64).sqrt();

    // T-statistics
    let t_naive = (mean_shading - target_naive) / se;
    let t_bne = (mean_shading - target_bne) / se;
    let critical_t = 2.01_f64; // approximate two-tailed t_crit for df~49, alpha=0.05

    // Prediction error metric
    let pred_errors: Vec<f64> = rounds.iter().map(|r| (r.shading - target_bne).abs()).collect();
    let mean_pred_error = pred_errors.iter().sum::<f64>() / n as f64;

    // BNE adherence rate (within 15 percentage points)
    let bne_adherence = shadings.iter().filter(|&&s| (s - target_bne).abs() < 0.15).count();
    let adherence_rate = bne_adherence as f64 / n as f64;

    println"'!("  +-----------------------------------------------+");
