fn robustness_checks(rounds: &[HumanAuctionRound]) {
    println!("'"\\n======================================================\");
    println"'!("  ROBUSTNESS CHECKS");
    println!("======================================================'"\\n\");

    // Check 1: Learning trend (shading by round quartile)
    println"'!("  (1) Learning trend: shading by round quartile");
    let q_size = rounds.len() / 4;
    for qi in 0..4 {
        let start = qi * q_size;
        let end = if qi == 3 { rounds.len() } else { (qi + 1) * q_size };
        let qs: Vec<f64> = rounds[start..end].iter().map(|r| r.shading).collect();
        if qs.is_empty() { continue; }
        let mean = qs.iter().sum::<f64>() / qs.len() as f64;
        println!("    Q{} (rounds {}-{}): mean_shading = {:.3}",
            qi + 1, start + 1, end, mean);
    }

    // Check 2: Shading by value level
    println!("'"\\n  (2) Shading by value level:\");
    for vtype in &[ValueType::Low, ValueType::MidLow, ValueType::MidHigh, ValueType::High] {
        let matching: Vec<&HumanAuctionRound> = rounds.iter()
            .filter(|r| r.bidders[r.winner_idx].1 == *vtype).collect();
        if matching.is_empty() { continue; }
        let avg_shade: f64 = matching.iter().map(|r| r.shading).sum::<f64>() / matching.len() as f64;
        println"'!("    Value {}: avg shading = {:.3} (n_obs = {})",
            vtype.label(), avg_shade, matching.len());
    }

    // Check 3: Shading stability (rolling window)
    println!("'"\\n  (3) Rolling 5-round mean shading (stability check):\");
    let window = 5usize;
    for start in (0..rounds.len()).step_by(window) {
        let end = (start + window).min(rounds.len());
        let chunk = &rounds[start..end];
        if chunk.is_empty() { continue; }
        let rm = chunk.iter().map(|r| r.shading).sum::<f64>() / chunk.len() as f64;
        let anchor = start + 1;
        println"'!("    Rounds {}-{:>2}: rolling_mean = {:.3}", anchor, end, rm);
    }
}

