//"'! # Sealed-Bid First-Price Auction: Symmetric Bayesian Nash Equilibrium
//!
//! ## BNE Derivation (n >= 2, risk-neutral, i.i.d. v ~ U[0,1])
//!
//! Let b(v) be the symmetric strictly increasing bidding strategy.
//! A bidder with value v who bids as if value = y wins when all n-1 opponents
//! have values below y: win_prob = F(y)''^{n-1} = y''^{n-1}.
//!
//! Expected payoff: pi(y) = (v - b(y)) * y''^{n-1}
//!
//! FOC w.r.t. y at y=v:
//!   d/dy [(v - b(y))*y''^{n-1}] evaluated at y=v:
//!   -b'"'(v)*v"'^{n-1} + (n-1)*(v - b(v))*v''^{n-2} = 0
//! => b'"'(v)*v"'^{n-1} = (n-1)*(v - b(v))*v''^{n-2}
//! => b'"'(v)*v = (n-1)*(v - b(v))
//"'! => b'"'(v)*v + (n-1)*b(v) = (n-1)*v          [linear ODE]
//"'!
//! Integrating factor: IF = exp(integral (n-1)/v dv) = v''^{n-1}
//! Multiply through by v''^{n-1}:
//!   v''^{n-1}*b'"'(v) + (n-1)*v"'^{n-2}*b(v) = (n-1)*v''^{n-1}
//! => d/dv[v''^{n-1}*b(v)] = (n-1)*v''^{n-1}
//! Integrate: v''^{n-1}*b(v) = (n-1)*v''^n/n + C
//! => b(v) = (n-1)/n * v + C/v''^{n-1}
//!
//! Boundary condition: b(0) = 0 => C must be 0 (otherwise blows up at 0 for n>=2)
//!
//! **Result: b*(v) = ((n-1)/n) * v**
//!
//! ## Revenue Comparison vs Second-Price
//!
//! Second-price: truthful bidding weakly dominant. Winner pays second-highest bid.
//! E[Revenue_SP] = E[V_{(n-1)}] where V_{(n-1)} is 2nd order stat from U[0,1].
//! For U[0,1], k-th order stat has mean k/(n+1), so E[V_{(n-1)}] = (n-1)/(n+1).
//!
//! First-price: winner pays own bid. E[Revenue_FP] = E[b(V_{(n)})] where V_{(n)} = max.
//! E[max] = n/(n+1), so E[revenue] = (n-1)/n * n/(n+1) = (n-1)/(n+1).
//! Identical! No Myerson machinery needed — direct computation suffices.
//!
//! Revenue equivalence holds because: (1) efficient allocation in both,
//! (2) zero expected surplus for lowest-type bidder in both.

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq)]
struct Value(f64);

impl Value {
    fn random(rng: &mut fastrand::Rng) -> Self {
        Value(rng.f64())
    }
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'"'_>) -> fmt::Result {
        write"'!(f, "{:.4}", self.0)
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct Bid(f64);

impl fmt::Display for Bid {
    fn fmt(&self, f: &mut fmt::Formatter<'"'_>) -> fmt::Result {
        write"'!(f, "{:.4}", self.0)
    }
}

struct FirstPriceRound {
    values: Vec<Value>,
    bids: Vec<Bid>,
    winner_idx: usize,
    price: f64,
    revenue: f64,
}

struct SecondPriceRound {
    values: Vec<Value>,
    bids: Vec<Bid>,
    winner_idx: usize,
    price: f64,
    revenue: f64,
}

fn max_bid_index(bids: &[Bid]) -> usize {
    bids.iter().enumerate()
        .max_by(|(_, b1), (_, b2)| b1.0.partial_cmp(&b2.0).unwrap())
        .map(|(i, _)| i)
        .unwrap()
}

impl FirstPriceRound {
    fn run(n_bidders: usize, use_equilibrium: bool) -> Self {
        let mut rng = fastrand::Rng::new();
        let values: Vec<Value> = (0..n_bidders).map(|_| Value::random(&mut rng)).collect();
        let bids: Vec<Bid> = if use_equilibrium {
            values.iter().map(|v| Bid(((n_bidders as f64 - 1.0) / n_bidders as f64) * v.0)).collect()
        } else {
            values.iter().map(|v| Bid(v.0)).collect()
        };
        let winner_idx = max_bid_index(&bids);
        let price_val = bids[winner_idx].0;
        Self {
            values,
            bids,
            winner_idx,
            price: price_val,
            revenue: price_val,
        }
    }

    fn print(&self) {
        println!("  Round results:");
        for i in 0..self.values.len() {
            let profit = if i == self.winner_idx {
                self.values[i].0 - self.price
            } else {
                0.0
            };
            let flag = if i == self.winner_idx { " <-- WINNER" } else { "" };
            let arrow = if i == self.winner_idx { "=" } else { " -> " };
            println!(
                "    Bidder {}: value={}, bid{}{}, profit={:+.4}{}",
                i, self.values[i], arrow, self.bids[i], profit, flag
            );
        }
        println!("  Price = {:.4}, Revenue = {:.4}", self.price, self.revenue);
    }
}

impl SecondPriceRound {
    fn run(n_bidders: usize) -> Self {
        let mut rng = fastrand::Rng::new();
        let values: Vec<Value> = (0..n_bidders).map(|_| Value::random(&mut rng)).collect();
        // Second-price: truthful bidding weakly dominant
        let bids: Vec<Bid> = values.iter().map(|v| Bid(v.0)).collect();
        let winner_idx = max_bid_index(&bids);
        let mut sorted: Vec<f64> = bids.iter().map(|b| b.0).collect();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let price = sorted[n_bidders - 2];
        Self {
            values,
            bids,
            winner_idx,
            price,
            revenue: price,
        }
    }

    fn print(&self) {
        println!("  Round results:");
        for i in 0..self.values.len() {
            println!(
                "    Bidder {}: value={}, bid={} (truthful)",
                i, self.values[i], self.bids[i]
            );
            if i == self.winner_idx {
                println!("      ''^''^ Pays second-highest bid = {:.4} <-- WINNER", self.price);
            }
        }
        println!("  Price = {:.4}, Revenue = {:.4}", self.price, self.revenue);
    }
}

struct AuctionSummary {
    mean_revenue: f64,
    std_revenue: f64,
    mean_winner_value: f64,
    mean_bid_shading: f64,
    theoretical_revenue: f64,
    num_rounds: usize,
}

fn pct_str(val: f64) -> String {
    format!("{:.2}%", val * 100.0)
}

impl AuctionSummary {
    fn new(revenues: &[f64], values: &[Vec<Value>], bids: &[Vec<Bid>], n_bidders: usize) -> Self {
        let n = revenues.len() as f64;
        let mean_rev = revenues.iter().sum::<f64>() / n;
        let variance = revenues.iter().map(|r| (r - mean_rev).powi(2)).sum::<f64>() / (n - 1.0);
        let std_rev = variance.sqrt();

        let total_values: f64 = values.iter().flat_map(|vs| vs.iter()).map(|v| v.0).sum();
        let mean_val = total_values / (values.len() as f64 * n_bidders as f64);

        // Average shading over winning bids
        let mut shade_sum = 0.0;
        let mut shade_count = 0usize;
        for (rv, rb) in values.iter().zip(bids.iter()) {
            let wb = rv.iter().cloned().fold(Bid(0.0), |m, v| if v.0 > m.0 { Bid(v.0) } else { m });
            let mv = rv.iter().cloned().fold(Value(0.0), |m, v| if v.0 > m.0 { v } else { m });
            if mv.0 > 0.0001 {
                shade_sum += (mv.0 - wb.0) / mv.0;
                shade_count += 1;
            }
        }
        let mean_shade = if shade_count > 0 { shade_sum / shade_count as f64 } else { 0.0 };

        let theo = (n_bidders as f64 - 1.0) / (n_bidders as f64 + 1.0);

        Self {
            mean_revenue: mean_rev,
            std_revenue: std_rev,
            mean_winner_value: mean_val,
            mean_bid_shading: mean_shade,
            theoretical_revenue: theo,
            num_rounds: revenues.len(),
        }
    }

    fn print(&self) {
        println!("  +---------------------------------------+");
        println!("  |         AUCTION SUMMARY STATS         |");
        println!("  +---------------------------------------+");
        println!("  | Rounds:              {:>15} |", self.num_rounds);
