//"'! # Live-Auction Experiment Design: Testing Bid Shading
//!
//! When you can only run 50 live auctions with real people (not simulations),
//! how do you detect whether bidders shade their bids according to BNE theory?
//!
//! == FULL EXPERIMENTAL PROTOCOL ==
//!
//! 1. Treatment Structure
//!    - Format: First-price sealed-bid auction
//!    - Bidders/round: n=3 (balanced competition-signal tradeoff)
//!    - Rounds/subject: 4 (~13 sessions yield 50 rounds)
//!    - Values: discrete {25,50,75,100}, p=0.25 each (U[0,1] via x/100)
//!
//! 2. Information
//!    - Pre-bid: private value only, partial info about "other participants"
//!    - Post-bid: outcome visibility (win/loss, winning bid, own payoff)
//!
//! 3. Payment
//!    - Real money with show-up fee; first-price payment rule
//!
//! 4. Confounders Controlled
//!    - Learning: counterbalanced value order across subjects
//!    - Risk aversion: separate Holt-Laury lottery elicitation
//!    - Communication: isolated terminals, no talking
//!    - Social prefs: post-auction dictator game vignette
//!    - Familiarity: rotating participants, no repeats within week
//!    - Strategy conf: 1 non-paying practice round + instruction quiz
//!    - Order effects: half low->high, half high->low
//!    - Income effects: fixed show-up fee regardless of performance
//!
//! 5. Pre-registered Primary Statistic
//!    T-test on mean bid shading. For each round i:
//!       shading_i = 1 - (winning_bid_i / winner_value_i)
//!    H_0: mean(shading) = 0.50 (naive "bid half my value")
//!    H_1: mean(shading) = 0.33 (BNE prediction for n=3)
//!    One-sample t-test at alpha=0.05, critical |t| > 2.01 (df~49)

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq)]
struct ParticipantId(u32);

impl fmt::Display for ParticipantId {
    fn fmt(&self, f: &mut fmt::Formatter<'"'_>) -> fmt::Result {
        write"'!(f, "P{:03}", self.0)
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum ValueType {
    Low, MidLow, MidHigh, High,
}

impl ValueType {
    fn value(self) -> f64 {
        match self { Self::Low => 25.0, Self::MidLow => 50.0, Self::MidHigh => 75.0, Self::High => 100.0 }
    }
    fn from_uniform(u: f64) -> Self {
        match u {
            v if v < 0.25 => Self::Low,
            v if v < 0.50 => Self::MidLow,
            v if v < 0.75 => Self::MidHigh,
            _ => Self::High,
        }
    }
    fn label(&self) -> &'"'static str {
        match self { Self::Low => \"25\", Self::MidLow => \"50\", Self::MidHigh => \"75\", Self::High => \"100\" }
    }
}

// Note: cannot derive Copy for HumanBid due to Option<String> field
#[derive(Debug, Clone)]
struct HumanBid {
    raw_bid: f64,
    strategy_label: Option<String>,
}

impl HumanBid {
    fn shading_ratio(&self, value: f64) -> f64 {
        if value <= 0.0001 { 0.0 } else { 1.0 - self.raw_bid / value }
    }
}

#[derive(Debug)]
struct HumanAuctionRound {
    round_id: usize,
    n_bidders: usize,
    bidders: Vec<(ParticipantId, ValueType, HumanBid)>,
    winner_idx: usize,
    winning_bid: f64,
    winning_value: f64,
    shading: f64,
}

impl HumanAuctionRound {
    fn print(&self) {
        println"'!("  Round {}: n={}, winner=P{}@{}",
            self.round_id, self.n_bidders,
            self.bidders[self.winner_idx].0,
            self.bidders[self.winner_idx].1.label());
        for (pid, val, bid) in &self.bidders {
            let shade = bid.shading_ratio(val.value());
            let mark = if pid == &self.bidders[self.winner_idx].0 { " <-- winner" } else { "" };
            let shade_pct = shade * 100.0;
            println!("    {:?}: val={:>3}, bid={:>5.0}, shade={:.1}%{}",
                pid, val.label(), bid.raw_bid, shade_pct, mark);
        }
    }
}

fn pct_str(val: f64) -> String {
    format!("{:.2}%", val * 100.0)
}

struct AnalysisPlan {
    experiment_id: String,
    num_auctions: usize,
    n_per_round: usize,
    theorized_bid_fraction: f64, // e.g. 2/3 means b*=2/3*v
    alpha: f64,
}

impl AnalysisPlan {
    fn default_for_n3() -> Self {
        Self {
            experiment_id: "FP-SBS-n3-50round".to_string(),
            num_auctions: 50,
            n_per_round: 3,
            theorized_bid_fraction: 2.0 / 3.0,
            alpha: 0.05,
        }
    }
    fn describe(&self) {
        println!("================================================================");
        println!("  PRE-REGISTERED EXPERIMENTAL DESIGN");
        println!("================================================================");
        println!("  Experiment ID:    {}", self.experiment_id);
        println!("  Total auctions:   {}", self.num_auctions);
        println!("  Bidders/round:    {}", self.n_per_round);
        let actual_shade = 1.0 - self.theorized_bid_fraction;
        println!("  Theory shade:     {} (bid = {:.0}% of value)",
            pct_str(actual_shade), self.theorized_bid_fraction * 100.0);
        println!("  Significance a:   {:.2}'"\\n\", self.alpha);

        println"'!("  Theoretical predictions:'"\\n\");
        for n_val in [2u32, 3, 4, 5, 10] {
            let bf = (*n_val as f64 - 1.0) / *n_val as f64;
            let shade = 1.0 - bf;
            println"'!("    n={:>2}: b*={:.2}v -> shade = {}", n_val, bf, pct_str(shade));
        }
    }
}

/// Mock human bid generator for pipeline testing
fn generate_mock_human_bids(n_rounds: usize, n_bidders: usize, noise_level: f64) -> Vec<HumanAuctionRound> {
    let mut rng = fastrand::Rng::new();
    let mut rounds = Vec::with_capacity(n_rounds);
    let mut pid_counter: u32 = 0;

    for round_id in 1..=n_rounds {
        let mut bidders = Vec::with_capacity(n_bidders);
        pid_counter += 1;

        for bidder_num in 0..n_bidders {
            let pid = ParticipantId(pid_counter + bidder_num as u32);
            let norm_val = rng.f64();
            let value_type = ValueType::from_uniform(norm_val);
            let actual_value = value_type.value();

            // BNE equilibrium bid + noise + systematic underbid bias
            let bne_bid = ((n_bidders as f64 - 1.0) / n_bidders as f64) * actual_value;
            let noise = rng.f64() * 2.0 * noise_level * actual_value - noise_level * actual_value;
            let underbid_bias = rng.f64() * actual_value * 0.08;
            let clamped = (bne_bid - underbid_bias + noise).max(0.0).min(actual_value);

            // 15% chance of naive behavior
            let naive_flag = rng.bool();
            let final_bid = if naive_flag { actual_value * 0.5 } else { clamped };

            let strat = if naive_flag {
                Some("naive(50%)".to_string())
            } else if (final_bid - bne_bid).abs() < actual_value * 0.05 {
                Some("near-BNE".to_string())
            } else {
                None
            };

            bidders.push((pid, value_type, HumanBid {
                raw_bid: final_bid,
                strategy_label: strat,
            }));
        }

        let wi = bidders.iter().enumerate()
            .max_by(|(_, b1), (_, b2)| b1.2.raw_bid.partial_cmp(&b2.2.raw_bid).unwrap())
            .map(|(i, _)| i).unwrap();
        let win_bid = bidders[wi].2.raw_bid;
        let win_val = bidders[wi].1.value();
        let shade = if win_val > 0.0001 { 1.0 - win_bid / win_val } else { 0.0 };

        rounds.push(HumanAuctionRound {
            round_id, n_bidders, bidders, winner_idx: wi,
            winning_bid: win_bid, winning_value: win_val, shading: shade,
        });
    }
    rounds
}

fn run_analysis(rounds: &[HumanAuctionRound], plan: &AnalysisPlan) {
    println!("'"\\n======================================================\");
    println"'!("  PRIMARY STATISTICAL TESTS");
    println!("======================================================'"\\n\");

    let n = rounds.len();
    let shadings: Vec<f64> = rounds.iter().map(|r| r.shading).collect();
    let mean_shade = shadings.iter().sum::<f64>() / n as f64;

    let target_bne = 1.0 - plan.theorized_bid_fraction;
    let target_naive = 0.50;

    let variance = shadings.iter().map(|s| (s - mean_shade).powi(2)).sum::<f64>() / (n as f64 - 1.0);
    let se = (variance / n as f64).sqrt();

    let t_naive = (mean_shade - target_naive) / se;
    let t_bne = (mean_shade - target_bne) / se;
    let crit_t = 2.01_f64;

    let pred_errors: Vec<f64> = rounds.iter().map(|r| (r.shading - target_bne).abs()).collect();
    let mean_pe = pred_errors.iter().sum::<f64>() / n as f64;

    let adhere = shadings.iter().filter(|&&s| (s - target_bne).abs() < 0.15).count();
    let ad_rate = adhere as f64 / n as f64;

    let strat_count = rounds.iter().filter(|r| {
        r.bidders[r.winner_idx].2.strategy_label.is_some()
    }).count();

    println"'!("  +-----------------------------------------------+");
    println!("  | SAMPLE STATISTICS                             |");
    println!("  +-----------------------------------------------+");
    println!("  | Sample size:             {:>17} |", n);
    println!("  | Mean shading:            {:>17} |", pct_str(mean_shade));
    println!("  | BNE target (n=3):        {:>17} |", pct_str(target_bne));
    println!("  | Naive target (50%):      {:>17} |", pct_str(target_naive));
    println!("  | SE of mean:              {:>17} |", pct_str(se));
    println!("  +-----------------------------------------------+");
    println!("  | T-TESTS (critical |t| > {:.2})                 |", crit_t);
    println!("  +-----------------------------------------------+");
    println!("  | t(H_0:shade=naive=50%):  {:>17} |", format!("{:+.3}", t_naive));
    if t_naive.abs() > crit_t {
        println!("  | Reject naive?             YES x           |");
    } else {
        println!("  | Reject naive?             NO  -           |");
    }
    println!("  | t(H_0:shade=BNE={:.3}):  {:>17} |", target_bne, format!("{:+.3}", t_bne));
    if t_bne.abs() < crit_t {
        println!("  | Consistent with BNE?      YES x           |");
    } else {
        println!("  | Consistent with BNE?      NO  -           |");
    }
    println!("  +-----------------------------------------------+");
    println!("  | PREDICTION ERRORS                             |");
    println!("  +-----------------------------------------------+");
    println!("  | Pred. error (mean):      {:>17} |", pct_str(mean_pe));
    println!("  | BNE adherence (>85%):    {:>17} |", pct_str(ad_rate));
    println!("  | Strategies detected:     {:>17} |", strat_count);
    println!("  +-----------------------------------------------+'"\\n\");

    // Distribution
    println"'!("  Shading distribution:");
    let bins: [(f64, f64, &str); 5] = [
        (0.0, 0.15, "Near-zero (underbidding)"),
        (0.15, 0.30, "Low shading"),
        (0.30, 0.50, "BNE-consistent (33%)"),
        (0.50, 0.70, "Naive (around 50%)"),
        (0.70, 1.01, "Heavy shading"),
    ];
    for &(lo, hi, label) in &bins {
        let count = shadings.iter().filter(|&&s| s >= lo && s < hi).count();
        let bar_len = (count as f64 / n as f64 * 40.0).ceil() as usize;
        println!("    [{:>.0}-{:>>.0}%-{}] {:>2} ({:>3})",
            lo * 100.0, hi * 100.0, label, count, pct_str(count as f64 / n as f64));
    }

    println!("'"\\n  Decision:\");
    if t_naive.abs() > crit_t && t_bne.abs() < crit_t {
        println"'!("    x H_0 (naive=50%) REJECTED, consistent with BNE shading.");
        println!("      Evidence supports theoretical prediction.");
    } else if t_naive.abs() < crit_t {
        println!("    - Cannot reject naive 50% shading. No evidence for BNE.");
    } else {
        println!("    ! Ambiguous: rejection of naive doesn'"'t confirm BNE precisely.\");
    }
}

fn robustness_checks(rounds: &[HumanAuctionRound]) {
    println"'!("'"\\n======================================================\");
    println"'!("  ROBUSTNESS CHECKS");
    println!("======================================================'"\\n\");

    println"'!("  (1) Learning trend (shading by round quartile):");
    let qsz = rounds.len() / 4;
    for qi in 0..4 {
        let start = qi * qsz;
        let end = if qi == 3 { rounds.len() } else { (qi + 1) * qsz };
        if start >= end { continue; }
        let qs: Vec<f64> = rounds[start..end].iter().map(|r| r.shading).collect();
        let avg = qs.iter().sum::<f64>() / qs.len() as f64;
        println!("    Q{} (rounds {}-{}): shade = {:.3}", qi + 1, start + 1, end, avg);
    }

    println!("'"\\n  (2) Shading by value level:\");
    for vt in &[ValueType::Low, ValueType::MidLow, ValueType::MidHigh, ValueType::High] {
        let matches: Vec<&HumanAuctionRound> = rounds.iter()
            .filter(|r| r.bidders[r.winner_idx].1 == *vt).collect();
        if matches.is_empty() { continue; }
        let avg: f64 = matches.iter().map(|r| r.shading).sum::<f64>() / matches.len() as f64;
        println"'!("    Value {}: shade = {:.3} (n={})", vt.label(), avg, matches.len());
    }

    println!("'"\\n  (3) Rolling 5-round stability:\");
    let window = 5usize;
    for start in (0..rounds.len()).step_by(window) {
        let end = (start + window).min(rounds.len());
        let chunk = &rounds[start..end];
        if chunk.is_empty() { continue; }
        let rm = chunk.iter().map(|r| r.shading).sum::<f64>() / chunk.len() as f64;
        println"'!("    Rounds {:>2}-{:>2}: rolling_mean = {:.3}", start + 1, end, rm);
    }
}

fn main() {
    println!("================================================================");
    println!("  LIVE-AUCTION EXPERIMENT DESIGN");
    println!("  Testing BNE Bid Shading with 50 Real Auctions");
